package com.tenora365.security;
import io.jsonwebtoken.*;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import javax.crypto.SecretKey;import java.nio.charset.StandardCharsets;import java.time.*;import java.util.*;
@Service public class JwtService{private final SecretKey key;private final long mins;public JwtService(@Value("${app.jwt.secret}")String secret,@Value("${app.jwt.access-minutes}")long mins){if(secret.length()<64)throw new IllegalArgumentException("JWT_SECRET must be at least 64 characters");key=Keys.hmacShaKeyFor(secret.getBytes(StandardCharsets.UTF_8));this.mins=mins;}public String create(Long uid,Long school,String role){Map<String,Object> c=new HashMap<>();c.put("uid",uid);c.put("schoolId",school);c.put("role",role);return Jwts.builder().claims(c).subject(String.valueOf(uid)).issuedAt(new Date()).expiration(Date.from(Instant.now().plusSeconds(mins*60))).signWith(key).compact();}public Claims parse(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();}}
